    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue

            # Get one connected outline component.
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)

            # Find zero cells enclosed inside this component's bounding box.
            zeros = {(y, x) for y in range(r0 + 1, r1)
                     for x in range(c0 + 1, c1) if grid[y][x] == 0}
            if not zeros:
                continue

            reachable = set()
            todo = []
            for y, x in zeros:
                if y in (r0 + 1, r1 - 1) or x in (c0 + 1, c1 - 1):
                    reachable.add((y, x))
                    todo.append((y, x))
            while todo:
                y, x = todo.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in zeros and p not in reachable:
                        reachable.add(p)
                        todo.append(p)
            enclosed = zeros - reachable
            if not enclosed:
                continue

            # Add the expanded rectangular border and fill enclosed areas.
            top, bottom = max(0, r0 - 1), min(h - 1, r1 + 1)
            left, right = max(0, c0 - 1), min(w - 1, c1 + 1)
            for y in range(top, bottom + 1):
                for x in range(left, right + 1):
                    if y in (top, bottom) or x in (left, right):
                        if grid[y][x] == 0:
                            out[y][x] = 2

            center_rows = {(r0 + r1) // 2}
            center_cols = {(c0 + c1) // 2}
            if (r1 - r0 + 1) % 2 == 0:
                center_rows.add((r0 + r1) // 2 + 1)
            if (c1 - c0 + 1) % 2 == 0:
                center_cols.add((c0 + c1) // 2 + 1)
            for y, x in enclosed:
                if y not in center_rows or x not in center_cols:
